// The 48px PixelLab fighters: assets/fighters/<class>.png (every frame side by side), <class>-portrait.png and
// <class>.json (frame layout, palette, feet column, team color), generated by tools/pixellab/build_frames.py.
import type { FrameId } from '../fighterFrames';

/** assets/fighters/<class>.json */
export interface FighterFile {
  /** One frame's size in sprite pixels (the strip is frames.length frames wide). */
  frameWidth: number; frameHeight: number;
  /** The frames in the strip, left to right; idle0 is the still sprite. */
  frames: FrameId[];
  /** Column of the feet in a frame, in sprite pixels. */
  ax: number;
  /** The main cloth or armor color (HUD ribbons; color skins recolor its hue family). One of the palette's colors. */
  team: string;
  /** Every color the art uses, by palette index; index 0 is the outline ink. */
  palette: string[];
}

export interface PlSet {
  /** Column of the feet, in sprite pixels. */
  ax: number;
  /** Palette letter of the main cloth or armor color (HUD ribbons; skins recolor its hue family). */
  team: string;
  /** Palette by letter (see letterIndex in sprites.ts); index 0 is the outline ink. */
  pal: string[];
  /** One frame's size in sprite pixels, and the portrait's. */
  w: number; h: number; portraitW: number; portraitH: number;
  /** Frames as palette rows, feet on the bottom row; idle0 is the still sprite. Read from the PNG on first use. */
  frames: Partial<Record<FrameId, string[]>>;
  /** 40x32 character select bust, as palette rows. Read from the PNG on first use. */
  portrait: string[];
}
